    order_map = {}  # id -> (side, price, arrival_time) for tracking
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, arr_time = order_map[cancel_id]
                # Remove from book if it exists
                book[side] = [(p, t, oid, q) for p, t, oid, q in book[side] if oid != cancel_id]
                del order_map[cancel_id]

        elif order[0] == 'market':
            _, incoming_id, side, qty = order
            opposite_side = 'sell' if side == 'buy' else 'buy'

            while qty > 0 and book[opposite_side]:
                if side == 'buy':
                    # Match against lowest price sells first
                    book[opposite_side].sort(key=lambda x: (x[0], x[1]))
